macro_rules! deps {
    () => {
        Outcome!();
        Change!();
        Item!();
        ResourceKind!();
        SourceTuple!();
        DiffLineStats!();
        Platform!();
        Error!();
    };
}

macro_rules! find_match {
    () => {
        deps!();
        # [doc = " Find `item` in our set of items ignoring `item_idx` to avoid finding ourselves, by similarity indicated by `percentage`."] # [doc = " The latter can be `None` or `Some(x)` where `x>=1` for identity, and anything else for similarity."] # [doc = " We also ignore emitted items entirely."] # [doc = " Use `kind` to indicate what kind of match we are looking for, which might be deletions matching an `item` addition, or"] # [doc = " any non-deletion otherwise."] # [doc = " Note that we always try to find by identity first even if a percentage is given as it's much faster and may reduce the set"] # [doc = " of items to be searched."] # [allow (clippy :: too_many_arguments)] fn find_match < 'a , T : Change > (items : & 'a [Item < T >] , item : & Item < T > , item_idx : usize , percentage : Option < f32 > , kind : visit :: SourceKind , stats : & mut Outcome , objects : & impl gix_object :: FindObjectOrHeader , diff_cache : & mut crate :: blob :: Platform , path_backing : & [u8] , num_checks : & mut usize ,) -> Result < Option < SourceTuple < 'a , T > > , emit :: Error > { let (item_id , item_mode) = item . change . id_and_entry_mode () ; if needs_exact_match (percentage) || item_mode . is_link () { let first_idx = items . partition_point (| a | a . change . id () < item_id) ; let range = items . get (first_idx ..) . map (| slice | { let end = slice . iter () . position (| a | a . change . id () != item_id) . map_or (items . len () , | idx | first_idx + idx) ; first_idx .. end }) ; let range = match range { Some (range) => range , None => return Ok (None) , } ; if range . is_empty () { return Ok (None) ; } let res = items [range . clone ()] . iter () . enumerate () . find_map (| (mut src_idx , src) | { src_idx += range . start ; * num_checks += 1 ; (src_idx != item_idx && src . is_source_for_destination_of (kind , item_mode)) . then_some ((src_idx , src , None)) }) ; if let Some (src) = res { return Ok (Some (src)) ; } } else if item_mode . is_blob () { let mut has_new = false ; let percentage = percentage . expect ("it's set to something below 1.0 and we assured this") ; for (can_idx , src) in items . iter () . enumerate () . filter (| (src_idx , src) | * src_idx != item_idx && src . is_source_for_destination_of (kind , item_mode)) { if ! has_new { diff_cache . set_resource (item_id . to_owned () , item_mode . kind () , item . location (path_backing) , ResourceKind :: NewOrDestination , objects ,) ? ; has_new = true ; } let (src_id , src_mode) = src . change . id_and_entry_mode () ; diff_cache . set_resource (src_id . to_owned () , src_mode . kind () , src . location (path_backing) , ResourceKind :: OldOrSource , objects ,) ? ; let prep = diff_cache . prepare_diff () ? ; stats . num_similarity_checks += 1 ; * num_checks += 1 ; match prep . operation { Operation :: InternalDiff { algorithm } => { let tokens = imara_diff :: InternedInput :: new (prep . old . intern_source () , prep . new . intern_source ()) ; let diff_result = imara_diff :: Diff :: compute (algorithm , & tokens) ; let removals_count = diff_result . count_removals () ; let insertions_count = diff_result . count_additions () ; let old_data_len = prep . old . data . as_slice () . unwrap_or_default () . len () ; let new_data_len = prep . new . data . as_slice () . unwrap_or_default () . len () ; let similarity = (old_data_len - removals_count as usize) as f32 / old_data_len . max (new_data_len) as f32 ; if similarity >= percentage { return Ok (Some ((can_idx , src , DiffLineStats { removals : removals_count , insertions : insertions_count , before : tokens . before . len () . try_into () . expect ("interner handles only u32") , after : tokens . after . len () . try_into () . expect ("interner handles only u32") , similarity , } . into () ,))) ; } } Operation :: ExternalCommand { .. } => { unreachable ! ("we have disabled this possibility with an option") } Operation :: SourceOrDestinationIsBinary => { } } } } Ok (None) }
    };
}

find_match!()